from dataclasses import dataclass
@dataclass
class Decision:
    valid:bool
    alert:bool
def check(valid,d):
    if not valid:
        return Decision(False,False)
    if d<0:
        raise ValueError('非法距离')
    return Decision(True,d<=35)
print(check(False,34))
print(check(True,34))

